def _format_float(value):
    value_str = str(value)
    if 'e' in value_str or 'E' in value_str:
        value_str = value_str.upper()
    elif '.' not in value_str:
        value_str += '.0'

    if 'E' in value_str:
        significand, exponent = value_str.split('E')
        if exponent[0] in ('+', '-'):
            sign = exponent[0]
            exponent = exponent[1:]
        else:
            sign = ''
        value_str = f'{significand}E{sign}{int(exponent):02d}'

    if len(value_str) > 20:
        value_str = f'{value:.16G}'
        if '.' not in value_str and 'E' not in value_str:
            value_str += '.0'
        elif 'E' in value_str:
            significand, exponent = value_str.split('E')
            if exponent[0] in ('+', '-'):
                sign = exponent[0]
                exponent = exponent[1:]
            else:
                sign = ''
            value_str = f'{significand}E{sign}{int(exponent):02d}'

    str_len = len(value_str)
    if str_len > 20:
        idx = value_str.find('E')
        if idx < 0:
            value_str = value_str[:20]
        else:
            value_str = value_str[: 20 - (str_len - idx)] + value_str[idx:]

    return value_str

# Test the specific case from the bug report
print('Bug report case:')
print(repr(_format_float(0.009125)))

test_values = [0.009125, 1.0, 0.0, -0.0, 1e-20, 1e20, 1.23456789012345678, 
               math.pi, 1/3, 1e100, 1e-100, 42.0, -1.5, 1e-7, 1e15,
               float('inf'), float('-inf'), 1e308, 5e-324]

print('\nAll test values:')
for v in test_values:
    result = _format_float(v)
    if math.isfinite(v):
        roundtrip = float(result) == v
    else:
        roundtrip = 'N/A'
    print(f'  {v!r:30s} -> {result!r:25s} len={len(result):2d} roundtrip={roundtrip}')
"

